// A typed service descriptor over a module generated by candid-core.
//
// The generated module carries each method's signature in `type Actor` and
// its mode (`query`, `composite_query`, `update`) in the service schema.
// Handles need both in the type, so the descriptor names the actor type and
// the method modes together:
//
//   export const LedgerService = defineService<Actor>()(actor, {
//     icrc1_balance_of: "query",
//     icrc1_transfer: "update",
//     ...
//   })
//
// and checks once, when it is built, that every declared mode is the
// schema's mode and that the two method sets are equal.
import type {
  AnyFieldSchema,
  MethodMode,
  ServiceMethod,
} from "@candid-core/schema"
import { serviceMethods } from "@candid-core/schema"

/** Any generated `Actor` type: method name → async function. */
export type ActorShape = {
  readonly [method: string]: (...args: never[]) => Promise<unknown>
}

/** One mode per method of `A`, and no other keys. */
export type ModeMap<A> = { readonly [K in keyof A & string]: MethodMode }

export interface ServiceDef<A extends ActorShape, M extends ModeMap<A>> {
  readonly schema: AnyFieldSchema
  readonly modes: M
  readonly methods: ReadonlyMap<string, ServiceMethod>
  /** Phantom: the generated actor interface. Never present at runtime. */
  readonly actor?: A
}

/**
 * `defineService<Actor>()(schema, modes)`. Curried so the actor interface is
 * given explicitly while the mode literals are inferred.
 */
export function defineService<A extends ActorShape>() {
  return <const M extends ModeMap<A>>(
    schema: AnyFieldSchema,
    modes: M & { readonly [K in Exclude<keyof M, keyof A>]: never }
  ): ServiceDef<A, M> => {
    const methods = serviceMethods(schema)
    const declared = modes as Readonly<Record<string, MethodMode>>
    for (const [name, method] of methods) {
      if (!(name in declared)) {
        throw new TypeError(
          `defineService: method ${name} is missing from the mode map`
        )
      }
      if (declared[name] !== method.mode) {
        throw new TypeError(
          `defineService: ${name} is declared ${declared[name]} but the schema says ${method.mode}`
        )
      }
    }
    for (const name of Object.keys(declared)) {
      if (!methods.has(name)) {
        throw new TypeError(`defineService: the schema has no method ${name}`)
      }
    }
    return { schema, modes, methods }
  }
}
